mapper.select:
select cast(grouped.target_batch as char) as targetId,
       (
           select latest.uav_model
             from data_fusion_target latest
            where latest.target_batch = grouped.target_batch
              and latest.timestamp >= #{startDateTime}
              and latest.timestamp < #{endDateTime}

              and latest.target_type = #{targetType}

            order by latest.timestamp desc, latest.id desc
            limit 1
       ) as uavModel,
       (
           select latest.target_type
             from data_fusion_target latest
            where latest.target_batch = grouped.target_batch
              and latest.timestamp >= #{startDateTime}
              and latest.timestamp < #{endDateTime}

              and latest.target_type = #{targetType}

            order by latest.timestamp desc, latest.id desc
            limit 1
       ) as targetType,
       grouped.timestampBegin,
       grouped.timestampEnd,
       timestampdiff(second, grouped.timestampBegin, grouped.timestampEnd) as duration,
       grouped.recordCount
  from (
        select dft.target_batch,
               min(dft.timestamp) as timestampBegin,
               max(dft.timestamp) as timestampEnd,
               count(1) as recordCount
          from data_fusion_target dft
         where dft.timestamp >= #{startDateTime}
           and dft.timestamp < #{endDateTime}

           and dft.target_type = #{targetType}

         group by dft.target_batch
  ) grouped
 order by grouped.timestampEnd desc
